-- Verify counts
SELECT l.slug, (SELECT COUNT(*) FROM wishlist_items i WHERE i.list_id = l.id AND i.is_seeded = true) AS item_count
FROM wishlist_lists l WHERE l.is_seeded = true ORDER BY l.slug;